import ast
import re
from pathlib import Path

path = Path('/testbed/qa_instances_eval/yt_dlp/sanitize_path_parts_loop_value_invariant_suite/files/test/qa/sanitize_path_parts_loop_value_invariant_suite_test.py')
mod = ast.parse(path.read_text())

calls = []
for node in mod.body:
    if isinstance(node, ast.ClassDef) and node.name == 'TestSanitizePathPartsLoopValueInvariantSuiteQA':
        for fn in node.body:
            if isinstance(fn, ast.FunctionDef):
                for stmt in fn.body:
                    if isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
                        call = stmt.value
                        if isinstance(call.func, ast.Name) and call.func.id == '_sanitize_path_parts':
                            parts = ast.literal_eval(call.args[0])
                            calls.append((fn.name, parts))


def instrument(parts):
    sanitized_parts = []
    iterations = 0
    violating = 0
    snapshots = []
    for part in parts:
        iterations += 1
        if not part or part == '.':
            pass
        elif part == '..':
            if sanitized_parts and sanitized_parts[-1] != '..':
                sanitized_parts.pop()
            else:
                sanitized_parts.append('..')
        else:
            sanitized_part = re.sub(r'[/<>:"\|\\?\*]|[\s.]$', '#', part)
            sanitized_parts.append(sanitized_part)

        inv = all(not p.endswith('.') for p in sanitized_parts)
        if not inv:
            violating += 1
        snapshots.append((part, list(sanitized_parts), inv))
    return iterations, violating, snapshots

total_i = 0
total_v = 0
for name, parts in calls:
    i, v, snaps = instrument(parts)
    total_i += i
    total_v += v
    print(name, parts, 'iters', i, 'viol', v)
    for s in snaps:
        print('  ', s)
print('TOTAL', total_i, total_v)
